# OSM sample
import osmium, itertools

class SampleHandler(osmium.SimpleHandler):
    def __init__(self):
        super().__init__()
        self.nodes = []
        self.ways = []
    def node(self, n):
        if len(self.nodes) < 4 and n.tags:
            tags = {k: v for k, v in n.tags}
            if tags:
                self.nodes.append({'id': n.id, 'lat': round(n.location.lat,5),
                                   'lon': round(n.location.lon,5), 'tags': dict(list(tags.items())[:2])})
    def way(self, w):
        if len(self.ways) < 3 and w.tags:
            tags = {k: v for k, v in w.tags}
            if 'highway' in tags or 'amenity' in tags:
                self.ways.append({'id': w.id, 'nodes': w.nodes.length,
                                  'tags': dict(list(tags.items())[:2])})

h = SampleHandler()
h.apply_file('data/raw/osm/beijing-latest.osm.pbf', locations=True)
print("北京 OSM 节点样本:")
for n in h.nodes[:3]:
    print(f"  node {n['id']}  ({n['lat']}, {n['lon']})  tags={n['tags']}")
print("北京 OSM 道路样本:")
for w in h.ways[:3]:
    print(f"  way {w['id']}  nodes={w['nodes']}  tags={w['tags']}")
EOF

