import osmium

class SampleHandler(osmium.SimpleHandler):
    def __init__(self):
        super().__init__()
        self.nodes = []
        self.ways = []
    def node(self, n):
        if len(self.nodes) < 3 and n.tags:
            tags = dict(list({k:v for k,v in n.tags}.items())[:2])
            if tags:
                self.nodes.append({'id':n.id,'lat':round(n.location.lat,5),'lon':round(n.location.lon,5),'tags':tags})
    def way(self, w):
        if len(self.ways) < 3 and w.tags:
            tags = {k:v for k,v in w.tags}
