import osmium
from collections import Counter
class RoleCounter(osmium.SimpleHandler):
    def __init__(self):
        super().__init__()
        self.roles = Counter()
    def relation(self, r):
        tags = dict(r.tags)
        if tags.get('route') == 'bus':
            for m in r.members:
                if m.type == 'n':
                    self.roles[m.role] += 1
h = RoleCounter()
h.apply_file('data/raw/osm/beijing-latest.osm.pbf')
print('Node member roles:', h.roles.most_common(10))
" 2>/dev/null

python3 -c "
import osmium
class RelationCounter(osmium.SimpleHandler):
    def __init__(self):
        super().__init__()
        self.node_ids = set()
        self.route_count = 0
    def relation(self, r):
        tags = dict(r.tags)
        if tags.get('route') == 'bus':
            self.route_count += 1
            for m in r.members:
                if m.type == 'n' and 'platform' in m.role:
                    self.node_ids.add(m.ref)
h = RelationCounter()
h.apply_file('data/raw/osm/beijing-latest.osm.pbf')
print(f'BJ: {h.route_count} routes, {len(h.node_ids)} unique platform nodes in relations')
" 2>/dev/null

python3 -c "
import osmium
class BusStopCount(osmium.SimpleHandler):
    def __init__(self):
        super().__init__()
        self.count = 0
        self.named = 0
    def node(self, n):
        if dict(n.tags).get('highway') == 'bus_stop':
            self.count += 1
            if 'name' in dict(n.tags):
                self.named += 1

class BusRouteCount(osmium.SimpleHandler):
    def __init__(self):
        super().__init__()
        self.route_count = 0
        self.node_ids = set()
    def relation(self, r):
        tags = dict(r.tags)
        if tags.get('route') == 'bus':
            self.route_count += 1
            for m in r.members:
                if m.type == 'n' and 'platform' in m.role:
                    self.node_ids.add(m.ref)

h1 = BusStopCount()
h1.apply_file('data/raw/osm/nyc-latest.osm.pbf', locations=True)
print(f'NYC bus_stop 节点: {h1.count}，有名称: {h1.named}')

h2 = BusRouteCount()
h2.apply_file('data/raw/osm/nyc-latest.osm.pbf')
print(f'NYC bus route 关系: {h2.route_count}，覆盖站点节点: {len(h2.node_ids)}')
print(f'关系覆盖率: {len(h2.node_ids)}/{h1.count} = {len(h2.node_ids)/h1.count*100:.1f}%')
" 2>/dev/null

